package org.marketreview.nativeapp;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.content.ContentValues;
import org.json.*;
import java.io.File;
import java.io.FileInputStream;
import java.io.InputStream;
import android.database.DatabaseErrorHandler;
import android.database.sqlite.SQLiteDatabaseCorruptException;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.marketreview.nativeapp.WatchlistWorkspaceModel.*;

public final class WatchlistReconciliationStore {
 private static final DatabaseErrorHandler KEEP_CORRUPT_FILE=corrupt->{throw new SQLiteDatabaseCorruptException("独立分组库损坏；原文件保留，拒绝自动删除或重建");};
 static boolean sqliteHeader(File file){try(InputStream in=new FileInputStream(file)){byte[] header=new byte[16];int offset=0,n;while(offset<header.length&&(n=in.read(header,offset,header.length-offset))>0)offset+=n;return offset==16&&Arrays.equals(header,"SQLite format 3\000".getBytes(StandardCharsets.US_ASCII));}catch(java.io.IOException error){return false;}}
 private final File file;private static final int LIMIT=32*1024*1024;
 public WatchlistReconciliationStore(Context c,String name)throws Exception{need(name!=null&&name.matches("[A-Za-z0-9._-]+")&&!name.equals(".")&&!name.equals(".."),"需已有独立分组库文件名");file=new File(c.getFilesDir(),name);try(SQLiteDatabase db=open(false)){}}
 public File filePath(){return file;}
 private static List<String> columns(SQLiteDatabase db,String table){List<String>out=new ArrayList<>();try(Cursor q=db.rawQuery("PRAGMA table_info("+table+")",null)){while(q.moveToNext())out.add(q.getString(1));}return out;}
 private static void guard(SQLiteDatabase db)throws Exception{try(Cursor q=db.rawQuery("PRAGMA application_id",null)){need(q.moveToFirst()&&q.getInt(0)==1465340725,"协调拒绝非本模块数据库，未写外库");}need(columns(db,"watchlist_workspace").equals(Arrays.asList("k","body","sha256")),"原配置侧表结构损坏，禁止重建");List<String>hs=columns(db,"watchlist_reconciliation_history"),ms=columns(db,"watchlist_reconciliation_meta");need(hs.isEmpty()==ms.isEmpty(),"协调历史演进不完整，禁止自动采用");if(!hs.isEmpty()){need(hs.equals(Arrays.asList("id","before_revision","after_revision","confirmed_at","preview_hash","body","sha256"))&&ms.equals(Arrays.asList("k","v")),"协调历史结构不支持，禁止重建");try(Cursor q=db.rawQuery("SELECT v FROM watchlist_reconciliation_meta WHERE k='schema'",null)){need(q.moveToFirst()&&q.getString(0).equals("1"),"协调历史版本不支持");}}}
 private SQLiteDatabase open(boolean write)throws Exception{need(file.isFile(),"需已有且已初始化的独立分组库；协调不新建数据库");need(sqliteHeader(file),"独立分组库文件头无效；保留原文件，未打开或重建");SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY,KEEP_CORRUPT_FILE);try{guard(db);if(write){db.close();db=SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,SQLiteDatabase.OPEN_READWRITE,KEEP_CORRUPT_FILE);guard(db);try(Cursor q=db.rawQuery("PRAGMA busy_timeout=1500",null)){q.moveToFirst();}}return db;}catch(Exception e){db.close();throw e;}}
 private static JSONObject body(SQLiteDatabase db,String table,String id)throws Exception{String key=table.equals("watchlist_workspace")?"k":"id",checksum;long length;try(Cursor q=db.rawQuery("SELECT length(body),sha256 FROM "+table+" WHERE "+key+"=?",new String[]{id})){if(!q.moveToFirst())return new JSONObject();length=q.getLong(0);checksum=q.getString(1);need(length>=0&&length<=LIMIT&&checksum!=null&&checksum.matches("[0-9a-f]{64}"),"协调记录长度或校验无效");}StringBuilder raw=new StringBuilder();for(long at=1;at<=length;at+=24000)try(Cursor q=db.rawQuery("SELECT substr(body,?,24000) FROM "+table+" WHERE "+key+"=?",new String[]{Long.toString(at),id})){need(q.moveToFirst(),"完整协调原文分块读取失败");raw.append(q.getString(0));}byte[]bytes=raw.toString().getBytes(StandardCharsets.UTF_8);need(bytes.length<=LIMIT&&WatchlistWorkspaceStore.sha(bytes).equals(checksum),"完整协调记录校验失败，未重建或截断");return new JSONObject(raw.toString());}
 private static JSONObject config(SQLiteDatabase db)throws Exception{JSONObject c=body(db,"watchlist_workspace","active");need(c.length()>0,"请先通过原Store显式初始化旧组");return WatchlistWorkspaceStore.validateConfig(c);}
 private static void evolve(SQLiteDatabase db)throws Exception{if(!columns(db,"watchlist_reconciliation_history").isEmpty())return;db.execSQL("CREATE TABLE watchlist_reconciliation_history(id TEXT PRIMARY KEY,before_revision TEXT NOT NULL,after_revision TEXT NOT NULL UNIQUE,confirmed_at TEXT NOT NULL,preview_hash TEXT NOT NULL UNIQUE,body TEXT NOT NULL,sha256 TEXT NOT NULL)");db.execSQL("CREATE TABLE watchlist_reconciliation_meta(k TEXT PRIMARY KEY,v TEXT NOT NULL)");db.execSQL("INSERT INTO watchlist_reconciliation_meta VALUES('schema','1')");guard(db);}
 private static void putHistory(SQLiteDatabase db,JSONObject r)throws Exception{WatchlistReconciliationModel.validateHistory(r);String raw=r.toString();byte[]bytes=raw.getBytes(StandardCharsets.UTF_8);need(bytes.length<=LIMIT,"完整协调历史超过32MiB，未截断或丢旧关系");ContentValues v=new ContentValues();v.put("id",r.getString("id"));v.put("before_revision",r.getJSONObject("beforeConfig").getString("revision"));v.put("after_revision",r.getJSONObject("afterConfig").getString("revision"));v.put("confirmed_at",r.getString("confirmedAt"));v.put("preview_hash",r.getString("previewHash"));v.put("body",raw);v.put("sha256",WatchlistWorkspaceStore.sha(bytes));db.insertOrThrow("watchlist_reconciliation_history",null,v);need(equal(body(db,"watchlist_reconciliation_history",r.getString("id")),r),"协调历史写后读取不一致");try(Cursor q=db.rawQuery("SELECT count(*) FROM watchlist_reconciliation_history",null)){need(q.moveToFirst()&&q.getLong(0)<=10000,"协调历史超过10000条，未自动删除");}}
 private static void putConfig(SQLiteDatabase db,JSONObject c)throws Exception{WatchlistWorkspaceStore.validateConfig(c);String raw=c.toString();byte[]bytes=raw.getBytes(StandardCharsets.UTF_8);need(bytes.length<=LIMIT,"协调配置超过32MiB");ContentValues v=new ContentValues();v.put("body",raw);v.put("sha256",WatchlistWorkspaceStore.sha(bytes));need(db.update("watchlist_workspace",v,"k='active'",null)==1,"协调配置更新失败，历史与配置一起回滚");need(equal(config(db),c),"协调配置写后读取不一致");}
 public static JSONObject evolutionPlan()throws Exception{return object("schema","watchlist-reconciliation-evolution/v1","applicationId",1465340725,"from","owned active config sidecar","addTables",new JSONArray().put("watchlist_reconciliation_history").put("watchlist_reconciliation_meta"),"historyVersion",1,"when","acknowledged confirm transaction only","activeSchemaUnchanged",true,"rebuild",false);}
 public JSONObject current(JSONObject inputs)throws Exception{try(SQLiteDatabase db=open(false)){db.execSQL("BEGIN");try{JSONObject out=copy(WatchlistWorkspaceStore.result(config(db),inputs));db.execSQL("COMMIT");return out;}catch(Exception e){db.execSQL("ROLLBACK");throw e;}}}
 public JSONObject preview(JSONObject inputs)throws Exception{try(SQLiteDatabase db=open(false)){db.execSQL("BEGIN");try{JSONObject out=copy(WatchlistReconciliationModel.preview(config(db),inputs));db.execSQL("COMMIT");return out;}catch(Exception e){db.execSQL("ROLLBACK");throw e;}}}
 public JSONObject confirm(JSONObject packet,JSONObject inputs,boolean acknowledged,String confirmedAt)throws Exception{need(acknowledged,"需明确接受完整旧配置入历史和本地关联协调");try(SQLiteDatabase db=open(true)){db.beginTransactionNonExclusive();try{guard(db);JSONObject before=config(db);need(equal(WatchlistReconciliationModel.preview(before,inputs),packet),"事务内配置版本、预览摘要或当前证券身份变化，未协调");if(packet.getBoolean("noChange")){JSONObject out=object("schema","watchlist-reconciliation-result/v1","state","noChange","config",before,"snapshot",WatchlistWorkspaceStore.inputSnapshot(inputs,text(before,"revision"),before.getJSONArray("groups")));db.setTransactionSuccessful();return copy(out);}JSONObject r=WatchlistReconciliationModel.archive(before,packet,inputs,WatchlistWorkspaceStore.revision(),confirmedAt);evolve(db);putHistory(db,r);JSONObject after=r.getJSONObject("afterConfig");putConfig(db,after);JSONObject out=object("schema","watchlist-reconciliation-result/v1","state","committed","historyId",r.get("id"),"previewHash",r.get("previewHash"),"config",after,"snapshot",WatchlistWorkspaceStore.inputSnapshot(inputs,text(after,"revision"),after.getJSONArray("groups")));db.setTransactionSuccessful();return copy(out);}finally{db.endTransaction();}}}
 public JSONArray historyList()throws Exception{try(SQLiteDatabase db=open(false)){JSONArray out=new JSONArray();if(columns(db,"watchlist_reconciliation_history").isEmpty())return out;try(Cursor q=db.rawQuery("SELECT id,before_revision,after_revision,confirmed_at,preview_hash FROM watchlist_reconciliation_history ORDER BY confirmed_at,id",null)){while(q.moveToNext()){need(out.length()<10000,"协调目录超过10000条，未截断");out.put(object("id",q.getString(0),"beforeRevision",q.getString(1),"afterRevision",q.getString(2),"confirmedAt",q.getString(3),"previewHash",q.getString(4)));}}return out;}}
 public JSONObject history(String id)throws Exception{try(SQLiteDatabase db=open(false)){need(!columns(db,"watchlist_reconciliation_history").isEmpty(),"尚无协调历史");db.execSQL("BEGIN");try{JSONObject r=WatchlistReconciliationModel.validateHistory(body(db,"watchlist_reconciliation_history",id));need(r.getString("id").equals(id),"协调历史主键不一致");try(Cursor q=db.rawQuery("SELECT before_revision,after_revision,confirmed_at,preview_hash FROM watchlist_reconciliation_history WHERE id=?",new String[]{id})){need(q.moveToFirst()&&q.getString(0).equals(r.getJSONObject("beforeConfig").getString("revision"))&&q.getString(1).equals(r.getJSONObject("afterConfig").getString("revision"))&&q.getString(2).equals(r.getString("confirmedAt"))&&q.getString(3).equals(r.getString("previewHash")),"协调历史索引与完整记录不一致");}db.execSQL("COMMIT");return copy(r);}catch(Exception e){db.execSQL("ROLLBACK");throw e;}}}
}
